/*!
 * UC Motion Core (runtime) v1.3.0-gsap
 * Author: andreyGRODZ
 * Homepage: https://andreygrodz.ru
 * Repository: https://github.com/andreyGRODZ/ucmotion
 * License: MIT
 */

(function (w, d) {
  'use strict';

  // ====== Guard / reuse ======
  const PREV = w.UCM || {};
  const REG = PREV.__REGISTRY instanceof Map ? PREV.__REGISTRY : new Map();
  let CSS_INJECTED_FOR = typeof PREV.__CSS_INJECTED_FOR === 'string' ? PREV.__CSS_INJECTED_FOR : '';

  // ====== Defaults (page-wide) ======
  const DEFAULTS = {
    effect: 'words',            // 'lines' | 'words' | 'letters'
    randomize: false,           // хаотичный порядок внутри строки
    baseDelay: 200,             // мс (если Basic выключен)
    delayBetweenLines: 60,      // мс
    parallelLines: true,        // строки параллельно
    parallelLineStagger: 60,    // мс (шаг старта между строками в параллели)
    letterWordDelay: 30,        // мс (шаг между словами/буквами)
    threshold: 0.4,             // доля видимости элемента для старта
    preferBasicDelay: true,     // попытаться взять задержку из Tilda Basic
    autoReset: false            // авто-сброс эффекта при уходе из viewport
  };
  let CONFIG = { ...DEFAULTS, ...(PREV.defaults || {}) };

  // ====== Utils ======
  const ready = (cb) =>
    d.readyState !== 'loading'
      ? cb()
      : d.addEventListener('DOMContentLoaded', cb, { once: true });

  const getAtom = (el) => {
    if (!el) return null;
    if (el.classList?.contains('tn-atom')) return el;
    return el.querySelector?.('.tn-atom') || null;
  };

  const toMs = (v) => Math.max(0, parseFloat(String(v).replace(',', '.')) * 1000 || 0);
  const hasBasic = (el) => el?.hasAttribute?.('data-animate-style');
  const readBasicDelay = (el, fallback) =>
    hasBasic(el) ? toMs(el.getAttribute('data-animate-delay') ?? '0') : fallback;

  function neutralizeBasic(el) {
    if (!el) return;
    el.style.transition = 'none';
    el.style.opacity = '1';
    el.style.transform = 'none';
    const atom = getAtom(el);
    if (atom) {
      atom.style.transition = 'none';
      atom.style.opacity = '1';
      atom.style.transform = 'none';
    }
  }

  // Внутренний CSS-инжект под выбранные селекторы эффектов
  function injectBasicNeutralizerFor(selectors) {
    if (!selectors || !selectors.length) return;
    const key = selectors.slice().sort().join('|');
    if (key === CSS_INJECTED_FOR) return;
    CSS_INJECTED_FOR = key;

    const css = `
      ${selectors.map((s) => `${s}.t-animate,${s}.t-animate_wait,${s}.t-animate_started`).join(',')}
        {opacity:1!important;transform:none!important;transition:none!important;}
      ${selectors.map((s) => `${s} [data-animate-style],${s} [data-animate-sbs-opts]`).join(',')}
        {animation:none!important;transition:none!important;}
      ${selectors.map((s) => `${s} .tn-atom`).join(',')}
        {opacity:1!important;transform:none!important;transition:none!important;display:inline-block!important;overflow:visible!important;}
      .uc-line{display:block;overflow:visible;line-height:inherit;}
      .uc-line.uc-gap{margin-top:0;}
      .uc-word,.uc-space,.uc-letter{display:inline-block;white-space:pre;will-change:opacity,transform,filter;}
    `.replace(/\s+/g, ' ');

    const tag = d.createElement('style');
    tag.type = 'text/css';
    tag.appendChild(d.createTextNode(css));
    d.head.appendChild(tag);
  }

  // Сохранение HTML-сущностей при побуквенном разборе
  function splitWithEntities(text) {
    return text
      .replace(/&[a-zA-Z0-9#]+;/g, '|$&|')
      .split('|')
      .flatMap((p) => (p.length > 1 && /^&.*;$/.test(p) ? [p] : [...p]));
  }

  // Бережное построение .uc-word/.uc-letter + разбиение по фактическим строкам
  function ensureWrapped(atom, mode) {
    if (!atom || atom.__ucWrapped) return;

    const html = atom.innerHTML.replace(/\[gap\]/g, '<span class="__gap-marker"></span>');
    const parts = html.replace(/(<[^>]+>)/g, '|$1|').split('|').filter(Boolean);

    let out = '';
    for (const part of parts) {
      if (part === '<span class="__gap-marker"></span>' || /^<br\s*\/?>$/i.test(part)) {
        out += part;
        continue;
      }
      if (part.startsWith('<') && part.endsWith('>')) {
        out += part; // сохраняем любые теги
        continue;
      }
      const tokens = part.split(/(\u00A0| )/);
      for (const tok of tokens) {
        if (tok === '\u00A0' || tok === ' ') {
          out += `<span class="uc-space">${tok}</span>`;
        } else if (mode === 'letters') {
          const letters = splitWithEntities(tok)
            .map((ch) => `<span class="uc-letter">${ch}</span>`)
            .join('');
          out += `<span class="uc-word">${letters}</span>`;
        } else {
          out += `<span class="uc-word">${tok}</span>`;
        }
      }
    }

    const vis = atom.style.visibility;
    atom.style.visibility = 'hidden';
    atom.innerHTML = out;

    // после рендеринга считаем фактические строки по offsetTop
    requestAnimationFrame(() => {
      const kids = [...atom.childNodes];
      const lines = [];
      let row = [];
      let top = null;

      for (const node of kids) {
        if (node.nodeType === 1 && node.classList?.contains('__gap-marker')) {
          if (row.length) lines.push({ nodes: row, isGap: false });
          lines.push({ nodes: null, isGap: true });
          row = [];
          top = null;
          continue;
        }
        if (!(node instanceof Element)) continue;
        if (node.tagName === 'BR') continue;

        const t = node.offsetTop;
        if (top === null) top = t;
        if (t !== top) {
          lines.push({ nodes: row, isGap: false });
          row = [];
          top = t;
        }
        row.push(node);
      }
      if (row.length) lines.push({ nodes: row, isGap: false });

      atom.innerHTML = '';
      for (const item of lines) {
        const div = d.createElement('div');
        div.className = 'uc-line';
        if (item.isGap) {
          div.classList.add('uc-gap');
          div.innerHTML = '&nbsp;';
        } else {
          item.nodes.forEach((n) => div.appendChild(n));
        }
        atom.appendChild(div);
      }

      atom.style.visibility = vis || 'visible';
      atom.__ucWrapped = mode || 'words';
      atom.__ucLinesBuilt = true;
    });
  }

  // Чтение классовых тогглов с элемента
  function readTogglesFrom(el, baseCfg) {
    const o = { ...baseCfg };
    const cls = [...el.classList];
    const has = (x) => el.classList.contains(x);
    const hit = (re) => cls.find((c) => re.test(c));

    if (has('uc-unit-lines')) o.effect = 'lines';
    if (has('uc-unit-words')) o.effect = 'words';
    if (has('uc-unit-letters')) o.effect = 'letters';
    if (has('uc-order-chaos')) o.randomize = true;
    if (has('uc-lines-serial')) o.parallelLines = false;

    const stg = hit(/^uc-stagger-(\d+)$/);
    if (stg) o.letterWordDelay = +stg.split('-').pop();

    const thr = hit(/^uc-threshold-(\d+)$/);
    if (thr) o.threshold = Math.min(1, Math.max(0, +thr.split('-').pop() / 100));

    return o;
  }

  const decideUnit = (cfg) =>
    cfg.effect === 'letters' ? 'letters' : cfg.effect === 'lines' ? 'lines' : 'words';

  // Планировщик по строкам/словам/буквам
  function scheduleByLines(atom, cfg, unit, cb /* (target, whenMs) */) {
    const all = [...atom.querySelectorAll('.uc-line')];
    let cumulative = 0;

    all.forEach((line, i) => {
      const targets =
        unit === 'letters'
          ? [...line.querySelectorAll('.uc-letter')]
          : unit === 'words'
          ? [...line.querySelectorAll('.uc-word,.uc-space')]
          : [line];

      const step = unit === 'lines' ? 0 : cfg.letterWordDelay;
      let order = targets.map((_, k) => k);
      if (cfg.randomize) order.sort(() => Math.random() - 0.5);

      const lineDelay = cfg.parallelLines ? cumulative + i * cfg.parallelLineStagger : cumulative;

      targets.forEach((t, j) => {
        const idx = cfg.randomize ? order[j] : j;
        cb(t, lineDelay + idx * step);
      });

      if (!cfg.parallelLines) {
        cumulative += unit === 'lines' ? cfg.delayBetweenLines : targets.length * step + cfg.delayBetweenLines;
      }
    });
  }

  // ====== Public API ======
  const UCM = {
    version: '1.3.0-gsap',
    defaults: { ...CONFIG },

    // глобальная настройка страницы
    config(overrides = {}) {
      CONFIG = { ...CONFIG, ...overrides };
      this.defaults = { ...CONFIG };
      return this;
    },

    // регистрация/снятие эффектов
    register(selector, handlers) {
      if (!selector || !handlers || typeof handlers.prepare !== 'function' || typeof handlers.run !== 'function') {
        return this;
      }
      REG.set(selector, handlers);
      return this;
    },
    unregister(selector) {
      REG.delete(selector);
      return this;
    },

    // запуск эффектов
    init(selector) {
      injectBasicNeutralizerFor([...REG.keys()]);

      const entries = selector
        ? [...d.querySelectorAll(selector)]
            .map((el) => ({ el, sel: [...REG.keys()].find((s) => el.matches(s)) }))
            .filter((x) => x.sel)
        : [...REG.keys()].flatMap((sel) => [...d.querySelectorAll(sel)].map((el) => ({ sel, el })));

      entries.forEach(({ sel, el }) => {
        if (el.__ucRan) return;
        const atom = getAtom(el);
        if (!atom) return;

        const cfg = readTogglesFrom(el, CONFIG);

        // 1) prepare
        try {
          REG.get(sel).prepare(el, cfg, this.util);
        } catch (e) {
          console.warn('[UCM prepare]', e);
        }

        // 2) стартовать только после построения линий
        const start = () => {
          if (el.__ucRan) return;
          if (!atom.__ucLinesBuilt) {
            requestAnimationFrame(start);
            return;
          }
          el.__ucRan = true;
          neutralizeBasic(el);
          try {
            REG.get(sel).run(el, cfg, this.util);
          } catch (e) {
            console.warn('[UCM run]', e);
          }
        };

        const delay = cfg.preferBasicDelay ? readBasicDelay(el, cfg.baseDelay) : cfg.baseDelay;

        // Observer на вход во viewport
        const io = new IntersectionObserver(
          (ents) => {
            ents.forEach((ent) => {
              if (!ent.isIntersecting) return;
              setTimeout(() => {
                start();
                io.unobserve(el);
              }, delay);
            });
          },
          { threshold: [0, cfg.threshold, 1] }
        );
        io.observe(el);

        // AutoReset (если модуль его поддерживает)
        if (cfg.autoReset && typeof REG.get(sel).reset === 'function') {
          const io2 = new IntersectionObserver(
            (ents) => {
              ents.forEach((ent) => {
                if (!ent.isIntersecting && el.__ucRan) {
                  el.__ucRan = false;
                  try {
                    REG.get(sel).reset(el, cfg, this.util);
                  } catch (_) {}
                  io.observe(el); // снова ждать вход
                }
              });
            },
            { threshold: [0, 0.01] }
          );
          io2.observe(el);
        }
      });

      return this;
    },

    // общие утилиты для модулей эффектов
    util: {
      ready,
      getAtom,
      toMs,
      hasBasic,
      readBasicDelay,
      neutralizeBasic,
      injectBasicNeutralizerFor,
      splitWithEntities,
      ensureWrapped,
      scheduleByLines,
      decideUnit,
      readTogglesFrom
    },

    __REGISTRY: REG,
    __CSS_INJECTED_FOR: CSS_INJECTED_FOR,
    __coreLoaded: true
  };

  // баннер в консоли
  (function banner() {
    if (w.__UCM_BANNER__) return;
    w.__UCM_BANNER__ = true;
    try {
      console.log('%cUC Motion core v' + UCM.version + ' — ready', 'color:#25EDFF;font-weight:600;');
    } catch (_) {}
  })();

  w.UCM = UCM;
})(window, document);
